def test_deny_unapproved_returns_deny():
    result = asyncio.run(_deny_unapproved("Bash", {"command": "ls"}, MagicMock()))
    assert result.behavior == "deny"
    assert "Bash" in result.message


def test_deny_unapproved_any_tool():
    result = asyncio.run(
        _deny_unapproved(
            "mcp__plugin_atlassian__searchJiraIssuesUsingJql",
            {"jql": "project = TEST"},
            MagicMock(),
        )
    )
    assert result.behavior == "deny"
    assert "not in the allowed" in result.message


